import * as React from "react";
import { Sparkles } from "lucide-react";

export interface ShinyGlowButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon?: React.ReactNode;
  children?: React.ReactNode;
}

/**
 * ShinyGlowButton — premium action button with a gradient body and a soft
 * outer glow that intensifies on hover. SSR-safe and keyboard accessible.
 */
export const ShinyGlowButton = React.forwardRef<
  HTMLButtonElement,
  ShinyGlowButtonProps
>(function ShinyGlowButton(
  { icon, children = "Launch Platform", className, ...rest },
  ref
) {
  const composed =
    "relative group inline-flex items-center justify-center px-6 py-3 bg-gradient-to-tr from-primary to-purple-600 font-bold text-white rounded-xl shadow-lg transition-all duration-300 hover:scale-[1.02] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/60 focus-visible:ring-offset-2 focus-visible:ring-offset-background disabled:opacity-60 disabled:pointer-events-none";
  return (
    <button ref={ref} className={[composed, className].filter(Boolean).join(" ")} {...rest}>
      <span
        aria-hidden
        className="absolute -inset-1 rounded-xl bg-gradient-to-tr from-primary to-purple-600 opacity-30 blur transition-opacity duration-300 group-hover:opacity-80"
      />
      <span className="relative flex items-center gap-2">
        {icon ?? <Sparkles className="w-4 h-4" aria-hidden />}
        <span>{children}</span>
      </span>
    </button>
  );
});

ShinyGlowButton.displayName = "ShinyGlowButton";

export default ShinyGlowButton;
